import { useEffect, useState } from 'react';

export default function App() {
  const [daftar, setDaftar] = useState(() => {
    const tersimpan = localStorage.getItem('belanja');
    return tersimpan ? JSON.parse(tersimpan) : [];
  });
  const [barang, setBarang] = useState('');

  useEffect(() => {
    localStorage.setItem('belanja', JSON.stringify(daftar));
  }, [daftar]);

  function tambah(e) {
    e.preventDefault();
    if (!barang.trim()) return;
    setDaftar([...daftar, { id: Date.now(), nama: barang.trim() }]);
    setBarang('');
  }

  return (
    <form onSubmit={tambah}>
      <input value={barang} onChange={(e) => setBarang(e.target.value)} placeholder="Barang" />{' '}
      <button type="submit">Tambah</button>
      <ul>{daftar.map((b) => <li key={b.id}>{b.nama}</li>)}</ul>
      <small>{daftar.length} barang tersimpan</small>
    </form>
  );
}

